import { getContext, setContext } from 'svelte'
import type { StoreProduct, StoreProductVariant } from '@medusajs/types'

// The reactive product context. `Product.Root` builds this from `$derived` values +
// pure-logic wrappers (see product-logic.ts) — no `$effect`, so it works during SSR.
export type ProductContext = {
	readonly product: StoreProduct | null
	readonly selectedVariant: StoreProductVariant | null
	readonly selectedVariantId: string
	isSelected: (valueId: string) => boolean
	isAvailable: (valueId: string) => boolean
	resolveVariant: (optionId: string, valueId: string) => string
	buildHref: (variantId: string) => string
	variantParam: string
	readonly quantity: number
	buildQuantityHref: (quantity: number) => string
	quantityParam: string
}

const KEY = Symbol('product')

export function setProductContext(ctx: ProductContext) {
	setContext(KEY, ctx)
}

export function getProductContext(): ProductContext {
	const ctx = getContext<ProductContext>(KEY)
	if (!ctx) throw new Error('Product.* must be used within <Product.Root>')
	return ctx
}

// Non-throwing lookup for components that may render standalone (CTAs, QuantitySelect).
export function getProductContextOptional(): ProductContext | null {
	return getContext<ProductContext>(KEY) ?? null
}

import { getContext, setContext } from 'svelte'
import type { ReviewSummary, StoreReview } from './review-types.js'

// The reactive reviews context. `Product.Reviews` builds this from `$derived` SDK queries +
// internal `$state` for rating/order/page — no `$effect`, so it works during SSR.
export type ReviewsContext = {
	readonly summary: ReviewSummary | null | undefined
	readonly reviews: StoreReview[]
	readonly count: number
	readonly filteredCount: number
	readonly loading: boolean
	readonly error: unknown
	readonly rating: number | null
	readonly order: string
	readonly page: number
	readonly pageSize: number
	readonly productId: string
	pushReview: (review: StoreReview) => void
	setRating: (n: number | null) => void
	setOrder: (s: string) => void
	setPage: (n: number) => void
}
export type ReviewItemContext = { readonly review: StoreReview }

const REVIEWS = Symbol('reviews')
const ITEM = Symbol('review-item')

export function setReviewsContext(ctx: ReviewsContext) {
	setContext(REVIEWS, ctx)
}
export function getReviewsContext(): ReviewsContext {
	const ctx = getContext<ReviewsContext>(REVIEWS)
	if (!ctx) throw new Error('Product.Reviews.* must be used within <Product.Reviews>')
	return ctx
}
export function getReviewsContextOptional(): ReviewsContext | null {
	return getContext<ReviewsContext>(REVIEWS) ?? null
}

export function setReviewItemContext(ctx: ReviewItemContext) {
	setContext(ITEM, ctx)
}
export function getReviewItemContextOptional(): ReviewItemContext | null {
	return getContext<ReviewItemContext>(ITEM) ?? null
}

// Per-level context for `Product.Reviews.Summary.Histogram` — set by the internal
// `product-reviews-histogram-level.svelte` provider, read by `Bar`/`Label`.
export type HistogramLevelContext = {
	readonly level: number
	readonly count: number
	readonly fill: number
	readonly active: boolean
	readonly orientation: 'horizontal' | 'vertical'
	select: () => void
}
const LEVEL = Symbol('histogram-level')

export function setHistogramLevelContext(ctx: HistogramLevelContext) {
	setContext(LEVEL, ctx)
}
export function getHistogramLevelContext(): HistogramLevelContext {
	const ctx = getContext<HistogramLevelContext>(LEVEL)
	if (!ctx) throw new Error('Histogram parts must be used within <Product.Reviews.Summary.Histogram>')
	return ctx
}

import type { Product, WithContext, Offer, AggregateOffer, Review } from 'schema-dts'
import type { StoreProduct, StoreProductVariant } from '@medusajs/types'
import { inStock, isPurchasable } from './product-logic.js'

export interface ProductSchemaOpts {
	url?: string
}

type ReviewLike = {
	rating?: number
	title?: string | null
	body?: string
	author_name?: string
	created_at?: string
	status?: string
}

function variantPrice(v: StoreProductVariant): { amount: number; currency: string } | null {
	const cp = v.calculated_price as
		| { calculated_amount?: number | null; currency_code?: string | null }
		| undefined
	if (cp?.calculated_amount == null || !cp.currency_code) return null
	return { amount: cp.calculated_amount, currency: cp.currency_code }
}

export function productSchema(
	product: StoreProduct | null,
	opts: ProductSchemaOpts = {}
): WithContext<Product> | null {
	if (!product) return null
	const variants = product.variants ?? []
	const prices = variants
		.map(variantPrice)
		.filter((p): p is { amount: number; currency: string } => p !== null)
	const availability = variants.some(v => inStock(v))
		? 'https://schema.org/InStock'
		: variants.some(v => isPurchasable(v))
			? 'https://schema.org/BackOrder'
			: 'https://schema.org/OutOfStock'

	const imgs = (product.images?.map(i => i.url).filter(Boolean) as string[] | undefined) ?? []
	const image = imgs.length ? imgs : product.thumbnail ? [product.thumbnail] : undefined

	const schema: WithContext<Product> = {
		'@context': 'https://schema.org',
		'@type': 'Product',
		name: product.title
	}
	if (product.description) schema.description = product.description
	if (image) schema.image = image
	if (variants.length === 1 && variants[0].sku) schema.sku = variants[0].sku

	if (prices.length) {
		const priceCurrency = prices[0].currency.toUpperCase()
		if (prices.length === 1) {
			const offer: Offer = {
				'@type': 'Offer',
				price: prices[0].amount,
				priceCurrency,
				availability
			}
			if (opts.url) offer.url = opts.url
			schema.offers = offer
		} else {
			const amounts = prices.map(p => p.amount)
			const agg: AggregateOffer = {
				'@type': 'AggregateOffer',
				lowPrice: Math.min(...amounts),
				highPrice: Math.max(...amounts),
				priceCurrency,
				offerCount: prices.length,
				availability
			}
			schema.offers = agg
		}
	}

	// Reviews: `review` is a custom relation (not on StoreProduct) — defensive cast; approved only.
	const rawReviews = (product as { review?: unknown }).review
	const reviews = (Array.isArray(rawReviews) ? (rawReviews as ReviewLike[]) : []).filter(
		r => r.status === 'approved' && typeof r.rating === 'number'
	)
	if (reviews.length) {
		const avg = reviews.reduce((s, r) => s + (r.rating ?? 0), 0) / reviews.length
		schema.aggregateRating = {
			'@type': 'AggregateRating',
			ratingValue: Math.round(avg * 10) / 10,
			reviewCount: reviews.length,
			bestRating: 5
		}
		schema.review = reviews.map((r): Review => {
			const rev: Review = {
				'@type': 'Review',
				reviewRating: { '@type': 'Rating', ratingValue: r.rating!, bestRating: 5 }
			}
			if (r.author_name) rev.author = { '@type': 'Person', name: r.author_name }
			if (r.title) rev.name = r.title
			if (r.body) rev.reviewBody = r.body
			if (r.created_at) rev.datePublished = r.created_at
			return rev
		})
	}
	return schema
}

import type { StoreProduct, StoreProductVariant } from '@medusajs/types'

// Pure variant-resolution + inventory-availability logic (no runes, no $app) so it is
// trivially unit-testable. `Product.Root` wires these into reactive `$derived` context.

// In stock when inventory isn't managed, or the managed quantity is positive.
export function inStock(
	v: Pick<StoreProductVariant, 'manage_inventory' | 'inventory_quantity'>
): boolean {
	return v.manage_inventory === false || (v.inventory_quantity ?? 0) > 0
}

// Map of option_id -> selected value_id for a variant (keyed by the option each value
// belongs to — NOT by array position, which isn't guaranteed to match product.options).
export function selectedByOption(variant: StoreProductVariant | null): Map<string, string> {
	const m = new Map<string, string>()
	for (const o of variant?.options ?? []) if (o.option_id) m.set(o.option_id, o.id)
	return m
}

export function optionIdOfValue(product: StoreProduct | null, valueId: string): string | undefined {
	return product?.options?.find(o => o.values?.some(v => v.id === valueId))?.id
}

function variantForValueIds(product: StoreProduct | null, valueIds: string[]): string | undefined {
	return product?.variants?.find(v => {
		const ids = v.options?.map(o => o.id) ?? []
		return valueIds.every(id => ids.includes(id))
	})?.id
}

// Highest-ranked (lowest rank) value per option → its variant; else the first variant.
export function defaultVariantId(product: StoreProduct | null): string {
	if (!product?.variants?.length) return ''
	if (product.options?.length) {
		const top = product.options
			.map(o => [...(o.values ?? [])].sort((a, b) => (a.rank ?? 0) - (b.rank ?? 0))[0]?.id)
			.filter(Boolean) as string[]
		const match = variantForValueIds(product, top)
		if (match) return match
	}
	return product.variants[0].id
}

export function isSelected(selectedVariant: StoreProductVariant | null, valueId: string): boolean {
	return selectedVariant?.options?.some(o => o.id === valueId) ?? false
}

// The variant you'd land on by picking `valueId` for its option while keeping the current
// selections for the OTHER options; falls back to any variant containing the value.
export function resolveVariant(
	product: StoreProduct | null,
	selectedVariant: StoreProductVariant | null,
	optionId: string,
	valueId: string
): string {
	const target = new Map(selectedByOption(selectedVariant))
	target.set(optionId, valueId)
	return (
		variantForValueIds(product, [...target.values()]) ??
		product?.variants?.find(v => v.options?.some(o => o.id === valueId))?.id ??
		''
	)
}

// Some IN-STOCK variant contains `valueId` AND matches the current selections for the
// OTHER options (relative availability).
export function isAvailable(
	product: StoreProduct | null,
	selectedVariant: StoreProductVariant | null,
	valueId: string
): boolean {
	const optId = optionIdOfValue(product, valueId)
	const others = [...selectedByOption(selectedVariant).entries()]
		.filter(([oid]) => oid !== optId)
		.map(([, vid]) => vid)
	return (
		product?.variants?.some(v => {
			const ids = v.options?.map(o => o.id) ?? []
			return ids.includes(valueId) && others.every(sel => ids.includes(sel)) && inStock(v)
		}) ?? false
	)
}

// Purchasable = a variant is selected AND it can be bought now (unmanaged, backorderable,
// or positive managed stock). Distinct from `inStock` (which ignores backorder) so option
// availability display is unchanged.
export function isPurchasable(variant: StoreProductVariant | null): boolean {
	if (!variant) return false
	if (variant.manage_inventory === false) return true
	if (variant.allow_backorder) return true
	return (variant.inventory_quantity ?? 0) > 0
}

// The inclusive upper bound for a quantity control: capped to managed stock when the variant
// is stock-limited (managed & no backorder), otherwise the caller's `max`.
export function effectiveMax(variant: StoreProductVariant | null, max: number): number {
	if (variant && variant.manage_inventory !== false && !variant.allow_backorder) {
		return Math.min(variant.inventory_quantity ?? 0, max)
	}
	return max
}

// The list of selectable quantities: min, min+step, … ≤ effectiveMax. Empty when out of stock.
export function quantityRange(
	variant: StoreProductVariant | null,
	opts: { min: number; step: number; max: number }
): number[] {
	const hi = effectiveMax(variant, opts.max)
	const out: number[] = []
	for (let n = opts.min; n <= hi; n += opts.step) out.push(n)
	return out
}

// Clamp `n` into [min, hi]; when hi < min (empty range / OOS) fall back to min.
export function clampQuantity(n: number, min: number, hi: number): number {
	if (hi < min) return min
	return Math.min(Math.max(n, min), hi)
}

// Clamp a URL-supplied quantity against a variant's managed stock (floor 1). No-op when the
// variant isn't stock-limited. Lets `Product.Root` expose a quantity the button can trust.
export function clampToStock(n: number, variant: StoreProductVariant | null): number {
	if (variant && variant.manage_inventory !== false && !variant.allow_backorder) {
		return Math.max(1, Math.min(n, variant.inventory_quantity ?? 0))
	}
	return Math.max(1, n)
}

// Pure rating math + formatting for the Reviews components. No Svelte, unit-testable.

/** 5 fill values (0 | 0.5 | 1) for an average, snapped to the nearest half star. */
export function averageToStarFills(average: number): number[] {
	const snapped = Math.round((average || 0) * 2) / 2
	return [1, 2, 3, 4, 5].map((i) => (snapped >= i ? 1 : snapped >= i - 0.5 ? 0.5 : 0))
}

/** 5 fill values (0 | 1) for an integer review rating. */
export function ratingToStarFills(rating: number): number[] {
	return [1, 2, 3, 4, 5].map((i) => ((rating || 0) >= i ? 1 : 0))
}

/** Fraction 0–1 of a histogram bar; 0 when there are no reviews. */
export function barFill(count: number, total: number): number {
	return total > 0 ? count / total : 0
}

/** Number of pages for a review count at a given page size. */
export function pageCount(count: number, pageSize: number): number {
	return pageSize > 0 ? Math.ceil((count || 0) / pageSize) : 0
}

/** Locale date string for a review's created_at; '' when the input isn't a valid date. */
export function formatReviewDate(iso: string, locale = 'en-US'): string {
	const d = new Date(iso)
	return isNaN(d.getTime())
		? ''
		: d.toLocaleDateString(locale, { year: 'numeric', month: 'long', day: 'numeric' })
}

// Local shapes for the ratings store API (the SDK returns these but doesn't export named types).

import type { RemoteForm } from '@sveltejs/kit'

export type StoreReview = {
	id: string
	rating: number
	title?: string | null
	body: string
	author_name: string
	created_at: string
	featured?: boolean
	status?: string
	product_id?: string | null
	customer_id?: string | null
}

export type ReviewSummary = {
	average: number
	count: number
	distribution: Record<1 | 2 | 3 | 4 | 5, number>
}

export type ReviewsListResponse = { reviews: StoreReview[]; count: number }

// Cast targets restoring `.current`/`.loading`/`.error`, which svelte-check drops from the
// SDK remote-query type (runtime is fine) — same approach as cart/types.ts CartQuery.
export type SummaryQuery = { current: ReviewSummary | null | undefined; loading?: boolean; error?: unknown }
export type ReviewsQuery = { current: ReviewsListResponse | null | undefined; loading?: boolean; error?: unknown }

export type ReviewFormResult = { ok: true; review: StoreReview } | { ok: false; code: string }
export type ReviewForm = RemoteForm<any, ReviewFormResult>
export type ReviewFormContext = {
	readonly form: ReviewForm
	readonly error: string
	readonly submitting: boolean
	readonly messages: Record<string, string>
	setOpen: (open: boolean) => void
}
export type ReviewFormMessages = Record<string, string>

export type CalculatedPrice = {
	calculated_amount?: number | null
	original_amount?: number | null
	currency_code?: string | null
}

// Medusa returns amounts in major units. Formats with the price's own currency.
// `locale` is pinned (default 'en-US') so server + client render identically — passing
// `undefined` would use the host locale (Node vs browser) and cause a hydration mismatch.
export function formatPrice(cp: CalculatedPrice | null | undefined, locale = 'en-US'): string {
	if (!cp || cp.calculated_amount == null || !cp.currency_code) return ''
	return new Intl.NumberFormat(locale, {
		style: 'currency',
		currency: cp.currency_code.toUpperCase()
	}).format(cp.calculated_amount)
}

import { setReviewFormContext } from './review-form-ctx.svelte.js'
import { resolveReviewMessage, reviewMessages } from './review-form-messages.js'
import type { ReviewForm, ReviewFormResult } from './review-form-ctx.svelte.js'
import type { StoreReview } from './review-types.js'

export interface CreateReviewFormOptions {
	form: ReviewForm
	pushReview: (review: StoreReview) => void
	setOpen: (open: boolean) => void
	messages?: Record<string, string>
	onsuccess?: (review: StoreReview) => void
	onerror?: (result: ReviewFormResult) => void
}

/**
 * Shared code for `Product.Reviews.Form`: provides the review-form context the submit/error
 * parts read, runs the native remote-form submission, maps failure codes to copy, pushes a
 * successful review into the reviews list, and exposes the enhanced `<form>` attributes.
 * Call it once from the form component's top-level script (component-init scope, so the
 * context is set correctly).
 */
export function createReviewForm(options: () => CreateReviewFormOptions) {
	let error = $state('')

	setReviewFormContext({
		get form() {
			return options().form
		},
		get error() {
			return error
		},
		get submitting() {
			return options().form.pending > 0
		},
		get messages() {
			return options().messages ?? reviewMessages
		},
		setOpen: (o) => options().setOpen(o)
	})

	const enhanced = options().form.enhance(async ({ submit }) => {
		error = ''
		const o = options()
		const msgs = o.messages ?? reviewMessages
		try {
			await submit()
		} catch {
			// A thrown submission produced no ReviewFormResult — a transport-level failure
			// (offline, server unreachable, dropped connection). Surface it as in-form copy
			// instead of letting it bubble up unhandled (which renders outside the form).
			const result: ReviewFormResult = { ok: false, code: 'network' }
			error = resolveReviewMessage(msgs, 'network')
			o.onerror?.(result)
			return
		}
		const r = o.form.result
		if (r?.ok) {
			o.pushReview(r.review)
			o.onsuccess?.(r.review)
		} else if (r) {
			error = resolveReviewMessage(msgs, r.code)
			o.onerror?.(r)
		}
	})

	return {
		/** Spread onto the `<form>` element. */
		get enhanced() {
			return enhanced
		},
		/** Clear the form-level error (wire to the form's `oninput`). */
		clearError() {
			error = ''
		}
	}
}

import { getContext, setContext } from 'svelte'
import type { ReviewFormContext } from './review-types.js'

export type { ReviewFormResult, ReviewForm, ReviewFormContext } from './review-types.js'

const REVIEW_FORM = Symbol('review-form')

export function setReviewFormContext(ctx: ReviewFormContext) {
	setContext(REVIEW_FORM, ctx)
}
export function getReviewFormContext(): ReviewFormContext {
	const ctx = getContext<ReviewFormContext>(REVIEW_FORM)
	if (!ctx) throw new Error('Product.Reviews.Form.* must be used within <Product.Reviews.Form>')
	return ctx
}

import type { ReviewFormMessages } from './review-types.js'

export type { ReviewFormMessages } from './review-types.js'

export const reviewMessages: ReviewFormMessages = {
	unauthenticated: 'Please sign in to write a review.',
	error: 'Something went wrong. Please try again.',
	network: 'Could not reach the server. Please check your connection and try again.',
	unknown: 'Something went wrong. Please try again.'
}

export function resolveReviewMessage(messages: ReviewFormMessages, code: string | undefined): string {
	return messages[code ?? 'unknown'] ?? messages.unknown ?? 'Something went wrong. Please try again.'
}
